import itertools
from pysat.solvers import Glucose3

def check_ramsey(n, r, b):
    solver = Glucose3()

    def var(i, j):
        if i > j:
            i, j = j, i
        idx = 0
        for x in range(n):
            for y in range(x + 1, n):
                idx += 1
                if x == i and y == j:
                    return idx

    for c in itertools.combinations(range(n), r):
        clause = [var(i, j) for i, j in itertools.combinations(c, 2)]
        solver.add_clause(clause)

    for c in itertools.combinations(range(n), b):
        clause = [-var(i, j) for i, j in itertools.combinations(c, 2)]
        solver.add_clause(clause)

    return solver.solve()

print("R(4,3) > 8:", check_ramsey(8, 4, 3))
print("R(4,3) > 9:", check_ramsey(9, 4, 3))
